using System;using System.IO;using System.Threading.Tasks;using System.Web.Script.Serialization;using XHLLauncher;
class ExportPreview {static void Main(string[] args){LauncherSettings s;using(var f=File.OpenRead(Path.Combine(args[0],"Manager Data","settings.xml")))s=(LauncherSettings)new System.Xml.Serialization.XmlSerializer(typeof(LauncherSettings)).Deserialize(f);s.PhoneViewEnabled=false;s.AutoBackup=false;s.AutoRestartOnCrash=false;using(var e=new DesktopEngine(Path.GetDirectoryName(args[1]),s,true)){e.Start().GetAwaiter().GetResult();Task.Delay(1500).Wait();e.Tick().GetAwaiter().GetResult();File.WriteAllText(args[1],new JavaScriptSerializer{MaxJsonLength=8*1024*1024}.Serialize(e.Snapshot(true,true)));}}}
